/* Sessions 1–8 (Weeks 1–4). Content only.
   Slide fields: k kind, h heading, p text, ic icon, pts [[icon,text]], cmp [[title,[items]]], demo, ex example, psy psychology link, tk takeaway, n presenter notes. */
COURSE.sessions.push(
/* ================= WEEK 1 ================= */
{ id:1, week:1, unit:'Introduction to ICT', ic:'💻', lo:[1], book:'Discovering Computers, Ch. 1',
  title:'ICT Fundamentals',
  sub:'Information, communication and technology; hardware, software, platforms, networks, and local vs cloud storage.',
  intro:'Think about the last hour. Did you check WhatsApp, open Google, or take a photo? Each of those used ICT. Today we take the word apart — <b>Information</b>, <b>Communication</b>, <b>Technology</b> — and see the components that make it work.',
  obj:['Define information, communication, technology and ICT in simple words.','Describe the input–process–output–storage cycle.','Distinguish hardware from software and name examples of each.','Explain ICT platforms, networks, local storage and cloud storage.','Describe how ICT components work together, using psychology examples.'],
  slides:[
    {k:'Introduction', h:'Introduction to ICT', ic:'🌐', p:'ICT is everywhere: in phones, classrooms, banks, hospitals and therapy rooms. Learning to use it well is now a basic life and career skill.', ex:'Before class today you may have used an alarm app, WhatsApp, Google Maps and mobile data — four ICT tools in one morning.', tk:'ICT is not only "computers" — it is how we handle information every day.', n:'Ask: "Name one ICT tool you used before coming here." Collect 8–10 answers on the board.'},
    {k:'Concept', h:'What is information?', p:'<b>Data</b> are raw facts (numbers, words, answers). <b>Information</b> is data that has been processed so that it is meaningful and useful.', demo:'dataflow', psy:'Twenty answers on a stress questionnaire are data; the student\'s total stress score and what it means is information.', tk:'Computers turn data into information.'},
    {k:'Concept', h:'What is communication?', ic:'📣', p:'<b>Communication</b> is sending and receiving information between people or devices: a sender, a message, a channel and a receiver.', pts:[['🧑','Sender — creates the message'],['✉️','Message — the information'],['📶','Channel — email, phone, internet'],['👂','Receiver — understands and responds']], tk:'ICT provides fast digital channels for communication.'},
    {k:'Concept', h:'What is technology?', ic:'🛠️', p:'<b>Technology</b> is the use of knowledge and tools to solve practical problems. In ICT it means electronic devices, programs and networks.', ex:'Paper registers → spreadsheets; letters → email; notice boards → Google Classroom.', tk:'Technology is a tool — its value depends on how we use it.'},
    {k:'Animation', h:'Meaning of ICT', p:'<b>Information and Communication Technologies</b> = all devices, software and networks used to <b>create, store, process and share information</b>. Every computer task follows the same cycle:', demo:'ipo', tk:'ICT = Information Technology (computing) + Communication Technology (networks).', n:'Run the animation, then ask a student to describe an ATM withdrawal using Input, Process, Output, Storage.'},
    {k:'Concept', h:'Hardware', p:'<b>Hardware</b> is every physical part of a computer system — the parts you can touch.', pts:[['⌨️','<b>Input:</b> keyboard, mouse, microphone, webcam, scanner'],['🧠','<b>Processing:</b> CPU (processor) — follows instructions'],['⚡','<b>Memory:</b> RAM — temporary working space'],['💾','<b>Storage:</b> SSD, hard disk, USB'],['🖥️','<b>Output:</b> monitor, printer, speakers, projector']], tk:'If you can touch it, it is hardware.', n:'Show real items: a USB drive, a mouse, a RAM stick if available.'},
    {k:'Animation', h:'One keypress through the hardware', demo:'hardware', tk:'RAM forgets when power goes off; storage remembers — save often!'},
    {k:'Concept', h:'Software', p:'<b>Software</b> is a set of instructions (programs) that tells hardware what to do.', cmp:[['System software',['Operating systems: Windows, macOS, Android, iOS, Linux','Manages hardware, files and security','Utilities: antivirus, backup tools']],['Application software',['Helps the user do a task','Word, Excel, Chrome, WhatsApp, Zoom','SPSS / JASP for statistics']]], tk:'The operating system runs the device; applications run on the operating system.'},
    {k:'Animation', h:'Hardware versus software', demo:'hwsw', ex:'A laptop (hardware) running MS Word (software) to type a psychology report.', tk:'Hardware is the body; software is the instructions that make it useful.'},
    {k:'Concept', h:'ICT platforms', ic:'🧩', p:'A <b>platform</b> is a base technology on which apps and services run and people connect.', pts:[['📱','Device platforms: Android, iOS, Windows'],['☁️','Productivity platforms: Microsoft 365, Google Workspace'],['💬','Communication platforms: WhatsApp, Zoom, Teams'],['🎓','Learning platforms: Google Classroom, Moodle, Coursera']], tk:'Platforms connect users, apps and services in one ecosystem.'},
    {k:'Concept', h:'Networks', ic:'📶', p:'A <b>network</b> connects two or more devices so they can share data and resources.', pts:[['🏠','<b>LAN</b> — Local Area Network: a home, computer lab or office'],['🌍','<b>WAN</b> — Wide Area Network: across cities or countries'],['🌐','<b>Internet</b> — the global network of networks'],['📡','Connections: Wi-Fi, mobile data (4G/5G), cables, Bluetooth']], demo:'network', tk:'Networks let information travel — the "communication" in ICT.'},
    {k:'Concept', h:'Local storage', ic:'💾', p:'<b>Local storage</b> keeps files on a device you physically own: laptop SSD/hard disk, USB flash drive, memory card, external hard drive.', cmp:[['Advantages',['Works without internet','Fast to open large files','You control the device']],['Risks',['Lost if device is lost, stolen or damaged','Hard to share','Viruses can corrupt files']]], tk:'Local = fast and offline, but risky if it is your only copy.'},
    {k:'Animation', h:'Cloud storage', p:'<b>Cloud storage</b> saves files on a provider\'s internet servers — Google Drive, OneDrive, Dropbox, iCloud — so you can open them on any signed-in device.', demo:'cloudsync', tk:'Cloud = access anywhere + backup, but needs internet and a strong password.'},
    {k:'Animation', h:'How ICT components work together', demo:'ecosystem', tk:'People + hardware + software + networks + storage → useful information.'},
    {k:'Example', h:'ICT in everyday life', pts:[['📲','Communication: WhatsApp, video calls, email'],['🏦','Money: mobile wallets, online banking'],['🎓','Study: Google Classroom, YouTube lectures, e-books'],['🛒','Shopping and services: Daraz, ride-hailing, food delivery'],['🏛️','Government services: online ID card and tax services']], tk:'Daily life in Pakistan increasingly runs on ICT.'},
    {k:'Example', h:'ICT in psychology', ic:'🧠', pts:[['💻','A laptop to write psychological assessment reports'],['📊','SPSS / Excel / JASP to analyse survey data'],['📧','Email and online forms to communicate with research participants'],['🗄️','Secure cloud folders to store research documents (with confidentiality)'],['🎥','Online counselling sessions via secure video']], psy:'Psychologists must protect client and participant data — ICT skills include privacy skills.', tk:'ICT skills are professional skills for psychologists.'}
  ],
  lab:{t:'Activity: ICT components in our academic environment', steps:['Work in pairs. Look around the classroom, lab and your own bags.','List at least 10 ICT items and classify each as Hardware, Software, Network, Storage (local/cloud) or Platform.','For your phone, open Settings → About and note the operating system, RAM and storage.','Choose one academic task (e.g., submitting an assignment) and draw how the components work together.'], out:'A classification table and a simple diagram; 3 pairs share with the class.'},
  disc:['Is a smartphone a computer? Why or why not?','Which is more important for a student — local storage or cloud storage? Defend your answer.','How could ICT make psychological services more accessible in rural areas? What could go wrong?'],
  mistakes:['Thinking RAM and storage are the same.','Calling the whole computer "the CPU".','Saying "internet" when meaning a web browser such as Chrome.','Keeping the only copy of important work on one USB drive.','Believing ICT means only computers — networks, software and people matter too.'],
  rev:['Data are raw facts; information is processed, meaningful data.','ICT = devices + software + networks to create, store, process and share information.','Input → Process → Output → Storage.','Hardware is physical; software is instructions (system vs application).','Networks: LAN, WAN, Internet. Storage: local vs cloud.'],
  hw:'Read <i>Discovering Computers</i>, Chapter 1. Write 5 lines on how ICT is used in a field you might work in (clinical, school, organisational psychology).',
  quiz:[
    {q:'A depression score calculated from 20 questionnaire answers is…', o:['Data','Information','Hardware','A network'], a:1, e:'Processed, meaningful output = information.'},
    {q:'Which is an <b>input</b> device?', o:['Monitor','Microphone','Printer','Speaker'], a:1, e:'A microphone sends sound into the computer.'},
    {q:'Windows and Android are…', o:['Application software','Operating systems (system software)','Hardware','Cloud storage'], a:1, e:'They manage the device and run applications.'},
    {q:'What happens to unsaved work when the power suddenly fails?', o:['It is safe in RAM','It is lost because RAM is temporary','It moves to the cloud','It prints automatically'], a:1, e:'RAM is volatile memory.'},
    {q:'Google Drive is an example of…', o:['Local storage','Cloud storage','An input device','A LAN'], a:1, e:'Files are stored on Google\'s servers.'}],
  terms:[['Data','Raw, unprocessed facts such as numbers or answers.'],['Information','Data processed into a meaningful, useful form.'],['ICT','Information and Communication Technologies: devices, software and networks used to create, store, process and share information.'],['Hardware','Physical parts of a computer system.'],['Software','Programs (instructions) that tell hardware what to do.'],['Operating system','System software that manages hardware and runs applications.'],['CPU','Central Processing Unit; the processor that executes instructions.'],['RAM','Random Access Memory; fast, temporary working memory.'],['Platform','A base technology on which apps and services run and users connect.'],['Network','Two or more connected devices that share data and resources.'],['Local storage','Saving files on a device you own, such as an SSD or USB.'],['Cloud storage','Saving files on remote servers accessed through the internet.']]
},
{ id:2, week:1, unit:'Introduction to ICT', ic:'🚀', lo:[1,2], book:'Discovering Computers, Ch. 1; Technology in Action',
  title:'Scope of ICT & Emerging Technologies',
  sub:'ICT in education, business, governance, healthcare, media, entertainment and psychology; AI, cloud, IoT, VR, AR and future trends.',
  intro:'Imagine a day without ICT: no online classes, no mobile banking, no hospital records, no YouTube. Today we map <b>where</b> ICT is used and look at the technologies that will shape your future career.',
  obj:['Describe how ICT is used in education, business, governance, healthcare, digital media and entertainment.','Explain how ICT supports psychology practice and research.','Define AI, cloud computing, IoT, VR and AR with examples.','Evaluate benefits and limitations of emerging technologies.'],
  slides:[
    {k:'Animation', h:'ICT beyond computers', p:'ICT is not just a computer on a desk — it powers almost every field of work and life.', demo:'scope', tk:'One set of technologies, many domains.'},
    {k:'Domain', h:'ICT in education', ic:'🎓', pts:[['🏫','Learning Management Systems: Google Classroom, Moodle'],['🎥','Online and recorded lectures'],['📝','Online quizzes with instant feedback'],['📚','Digital libraries and e-books (e.g., HEC Digital Library)']], ex:'A teacher posts slides and an assignment on Google Classroom; students submit from their phones.', tk:'ICT makes learning flexible and accessible.'},
    {k:'Domain', h:'ICT in business', ic:'💼', pts:[['🛒','E-commerce: online stores and marketplaces'],['💳','Digital payments and mobile wallets'],['📊','Spreadsheets and data analysis for decisions'],['🤝','Email, video meetings and remote work']], ex:'A small clothing brand sells through Instagram and receives payments by mobile wallet.', tk:'ICT reduces cost and reaches more customers.'},
    {k:'Domain', h:'ICT in governance', ic:'🏛️', pts:[['🪪','Online identity services (NADRA)'],['🧾','Online tax filing (FBR IRIS)'],['📢','Citizen complaint portals'],['🎓','Online degree attestation (HEC)']], tk:'E-governance makes services faster and more transparent.', n:'Ask which government service students or their families have used online.'},
    {k:'Animation', h:'ICT in healthcare', p:'Hospitals and clinics use ICT to book, record, consult and follow up.', demo:'healthflow', tk:'Digital health widens access — privacy of records is essential.'},
    {k:'Domain', h:'ICT in digital media', ic:'📰', pts:[['📰','Online news websites and apps'],['🎙️','Podcasts and blogs'],['🎨','Graphic design tools: Canva, Photoshop'],['📱','Social media content creation']], tk:'Anyone can publish — so everyone must check accuracy.'},
    {k:'Domain', h:'ICT in entertainment', ic:'🎬', pts:[['📺','Streaming: YouTube, Netflix, Spotify'],['🎮','Online and mobile games'],['🎟️','Online ticket booking'],['🥽','Virtual-reality experiences']], psy:'Psychologists study screen time, gaming disorder and media effects on mood.', tk:'Entertainment is a major ICT industry — with well-being effects.'},
    {k:'Domain', h:'ICT in psychology', ic:'🧠', pts:[['💻','Computer-based tests and online surveys'],['📊','Statistical software for research (SPSS, JASP, R)'],['🎥','Telepsychology — counselling via secure video'],['📱','Mental-health and mood-tracking apps'],['🔎','Research databases: Google Scholar, APA PsycInfo']], tk:'ICT supports assessment, therapy, research and education in psychology.'},
    {k:'Emerging', h:'Artificial Intelligence (AI)', ic:'🤖', p:'Computer systems that perform tasks needing human-like intelligence — understanding language, recognising images, making predictions — by learning patterns from data.', pts:[['💬','Chatbots and AI assistants'],['🗣️','Voice typing and automatic captions'],['🎯','Recommendations on YouTube/Netflix']], demo:'ailearn', tk:'AI is powerful but can be wrong or biased — always verify.'},
    {k:'Emerging', h:'Cloud computing', ic:'☁️', p:'Using storage, software and computing power <b>over the internet</b>, on demand, instead of owning everything locally.', ex:'Google Docs runs in a browser; your files and the software live on Google\'s servers.', tk:'Rent instead of buy — access from anywhere.'},
    {k:'Emerging', h:'Internet of Things (IoT)', ic:'📡', p:'Everyday objects with <b>sensors</b> that collect and send data over the internet.', pts:[['⌚','Smartwatches and fitness bands'],['🏠','Smart home devices, smart meters'],['🚗','Car trackers'],['🏥','Remote patient monitors']], tk:'IoT turns objects into data sources — useful, but raises privacy questions.'},
    {k:'Emerging', h:'Virtual Reality (VR)', ic:'🥽', p:'A headset places you inside a fully <b>computer-generated world</b>.', psy:'VR exposure therapy is studied and used to help people with phobias (e.g., fear of heights) face situations gradually and safely, under a therapist\'s guidance.', tk:'VR = a fully virtual environment.'},
    {k:'Emerging', h:'Augmented Reality (AR)', ic:'📱', p:'AR <b>adds digital objects to the real world</b> through a phone camera or smart glasses.', ex:'Snapchat filters, Google Lens translating a sign, a 3-D brain model appearing on your desk for a biopsychology class.', tk:'AR = real world + digital layer.'},
    {k:'Animation', h:'Emerging ICT trends', demo:'emerging', tk:'AI, IoT, cloud, AR/VR, blockchain and 5G are shaping the next decade.'},
    {k:'Evaluate', h:'Benefits and limitations', cmp:[['Benefits',['Access to education and health care from anywhere','Faster services, new jobs, remote work','New tools for research and therapy']],['Limitations',['Privacy risks and data misuse','Digital divide — cost, connectivity, skills','Misinformation, over-use, AI errors and bias']]], tk:'Technology helps most when used responsibly and fairly.'}
  ],
  lab:{t:'Activity: ICT solves a real problem', steps:['In groups of 3, choose one ICT technology (e.g., telemedicine app, Google Classroom, mobile wallet, VR, an AI tool).','Identify a real problem it solves in Pakistan (who has the problem? what was difficult before?).','Explain how the technology solves it — draw a simple flow.','List one risk or limitation and one way to reduce it.'], out:'2-minute group presentation to the class.'},
  disc:['Which emerging technology will most change psychology work in the next 10 years? Why?','Should students be allowed to use AI tools for assignments? Under what rules?','Who might be left behind by digital services, and how can that be fixed?'],
  mistakes:['Thinking AI answers are always correct or have real references.','Confusing VR (fully virtual) with AR (adds to the real world).','Assuming everyone has internet and a smartphone.','Ignoring privacy when using health or IoT devices.'],
  rev:['ICT is used in education, business, governance, healthcare, media, entertainment and psychology.','AI learns patterns from data; it can be wrong or biased.','Cloud computing = computing resources over the internet.','IoT = connected sensors in everyday objects.','VR = fully virtual; AR = digital layer on the real world.'],
  hw:'Find one news article (from a reliable source) about AI or VR in mental-health care. Write 3 lines: what it does, one benefit, one concern.',
  quiz:[
    {q:'Online tax filing and ID card services are examples of ICT in…', o:['Entertainment','Governance','Gaming','Hardware'], a:1, e:'E-governance delivers public services online.'},
    {q:'A smartwatch sending heart-rate data to an app is an example of…', o:['IoT','Blockchain','LAN','Word processing'], a:0, e:'Internet of Things.'},
    {q:'A therapist uses a headset to gradually expose a client to a virtual high balcony. This is…', o:['AR','VR','Cloud storage','Email'], a:1, e:'Virtual Reality creates a fully virtual environment.'},
    {q:'Google Lens showing a translation over a real sign is…', o:['VR','AR','IoT','A LAN'], a:1, e:'AR adds digital information to the real view.'},
    {q:'Which is a <b>limitation</b> of emerging ICT?', o:['Faster services','Digital divide and privacy risks','Remote access','New jobs'], a:1, e:'Not everyone has access, and data can be misused.'}],
  terms:[['E-governance','Delivery of government services and information using ICT.'],['Artificial Intelligence','Computer systems that perform tasks needing human-like intelligence by learning from data.'],['Cloud computing','Using computing resources such as storage and software over the internet on demand.'],['IoT','Internet of Things: everyday objects with sensors connected to the internet.'],['Virtual Reality','A fully computer-generated environment experienced through a headset.'],['Augmented Reality','Digital information layered on top of the real world.'],['Digital divide','The gap between people who have access to ICT and skills and those who do not.'],['Telepsychology','Psychological services delivered using telecommunication technologies.']]
},
/* ================= WEEK 2 ================= */
{ id:3, week:2, unit:'Basic ICT productivity tools', ic:'🔎', lo:[2,3], book:'Technology in Action — Internet & search',
  title:'Internet & Search Engines',
  sub:'Internet vs Web, how Google and Bing work, keywords, search operators, academic searching and evaluating sources.',
  intro:'Your teacher asks for "three reliable sources on exam anxiety". You type it into Google and get 50 million results. Which ones can you trust? Today you learn to search like a researcher.',
  obj:['Distinguish the Internet from the World Wide Web.','Explain how a search engine crawls, indexes and ranks pages.','Use effective keywords and search operators.','Search for academic information using Google Scholar.','Evaluate websites and identify misleading information.'],
  slides:[
    {k:'Concept', h:'Internet introduction', ic:'🌐', p:'The <b>Internet</b> is a global network of networks connecting billions of devices. It carries email, video calls, messaging, online games and the web.', tk:'The Internet is the infrastructure — the "roads".'},
    {k:'Concept', h:'What is the World Wide Web?', ic:'🕸️', p:'The <b>Web</b> is a collection of web pages linked by hyperlinks, opened in a <b>browser</b> (Chrome, Edge, Firefox, Safari) using an address called a <b>URL</b>.', ex:'https://www.who.int/news-room/fact-sheets — protocol (https), domain (who.int), path.', tk:'"https" + padlock = encrypted connection (not a guarantee of truth!).'},
    {k:'Compare', h:'Internet versus Web', cmp:[['Internet',['The physical network of connected computers','Carries many services: email, WhatsApp, Zoom, web','Started in the 1960s–80s']],['World Wide Web',['One service on the internet: linked pages','Opened with a browser','Invented by Tim Berners-Lee (1989)']]], tk:'The Web runs on the Internet — they are not the same thing.'},
    {k:'Animation', h:'What is a search engine?', p:'A <b>search engine</b> is a web service that finds pages matching your words.', demo:'searchpipe', tk:'Browser opens pages; search engine finds them.'},
    {k:'Tool', h:'Google', ic:'🔍', pts:[['🌍','The most widely used search engine in Pakistan and worldwide'],['🧰','Tabs: All, Images, News, Videos, Books, Maps'],['🎓','Google Scholar for academic papers'],['🖼️','Google Lens for image search']], tk:'Learn its tools, not just its search box.'},
    {k:'Tool', h:'Bing', ic:'🅱️', pts:[['🪟','Microsoft\'s search engine, default in Edge and Windows'],['🤖','Integrates Microsoft Copilot AI answers'],['🖼️','Strong image and video search'],['🔁','Results may differ from Google — compare both']], tk:'Different engines rank differently; try more than one.'},
    {k:'Skill', h:'Search keywords', pts:[['✂️','Use key ideas, not full sentences: <i>sleep deprivation memory students</i>'],['🔁','Try synonyms: <i>anxiety / stress / worry</i>'],['🎯','Be specific: <i>exam anxiety university Pakistan</i>'],['🌐','Use correct technical terms: <i>cognitive behavioural therapy</i>']], tk:'Better words in → better results out.'},
    {k:'Skill', h:'Effective searching', pts:[['1️⃣','Start broad, then narrow'],['2️⃣','Scan titles and snippets before clicking'],['3️⃣','Use Tools → Time to get recent results'],['4️⃣','Change keywords if results are poor'],['5️⃣','Open several sources and compare']], tk:'Searching is a process, not one click.'},
    {k:'Animation', h:'Search operators', demo:'operators', pts:[['❝','<b>"exact phrase"</b>'],['🌐','<b>site:</b>who.int'],['📄','<b>filetype:</b>pdf'],['➖','<b>-word</b> to exclude'],['🔀','<b>OR</b> for alternatives']], tk:'Combine operators for precise searches.'},
    {k:'Skill', h:'Searching academic information', ic:'🎓', pts:[['🎓','scholar.google.com — journal articles, theses, books'],['📈','"Cited by" shows influence'],['❝','Cite button gives an APA citation (check it!)'],['🆓','[PDF] links for free full text'],['🏛️','HEC Digital Library through your university']], tk:'Use Scholar and library databases — not random blogs — for assignments.', n:'Live demo: search "social media use loneliness" in Scholar.'},
    {k:'Concept', h:'Search results', pts:[['💰','<b>Sponsored</b> results are paid ads'],['📄','<b>Organic</b> results are ranked by the algorithm'],['🤖','<b>AI overviews</b> summarise — open the sources to verify'],['📌','Featured snippets & "People also ask" boxes']], tk:'Top result ≠ best or truest result.'},
    {k:'Skill', h:'Evaluating websites — CRAAP', pts:[['🕒','<b>Currency</b> — is it recent?'],['🎯','<b>Relevance</b> — does it fit my question?'],['🎓','<b>Authority</b> — who wrote it? qualifications?'],['🔬','<b>Accuracy</b> — evidence and references?'],['🎯','<b>Purpose</b> — inform, sell or persuade?']], tk:'Check before you trust.'},
    {k:'Concept', h:'Reliable sources', cmp:[['Usually reliable',['Peer-reviewed journals','Government & university sites (.gov, .edu, .edu.pk)','WHO, APA, reputable news outlets']],['Use with caution',['Anonymous blogs & forums','Social-media posts','Sites selling a product']]], tk:'Prefer sources with named authors, evidence and accountability.'},
    {k:'Skill', h:'Identifying misleading information', pts:[['😱','Emotional headlines and "miracle cure" promises'],['❓','No author, no date, no references'],['💊','Selling a product alongside the "advice"'],['🔗','Look-alike domains (who-health.info vs who.int)']], tk:'If it sounds too good to be true, investigate.'},
    {k:'Example', h:'Psychology research example', ic:'🧪', p:'Question: <i>Does social media use affect sleep in university students?</i>', pts:[['🔍','Google Scholar: "social media" sleep "university students"'],['⏱️','Filter: since 2020'],['📄','Pick 3 peer-reviewed articles; note authors & year'],['🌐','Add WHO/university pages for background'],['✅','Apply CRAAP to each']], tk:'A good search plan saves hours.'}
  ],
  lab:{t:'Activity: Compare source reliability', steps:['Search "benefits of mindfulness for students" on Google and Google Scholar.','Pick 3 results: one journal article, one organisation page, one blog/social post.','Apply CRAAP to each (score each criterion 0–1).','Use at least two operators to find a PDF report from WHO or a university.','Write which source you would cite and why.'], out:'A short comparison table in a Google Doc.'},
  disc:['Why might two people get different results for the same search?','Is Wikipedia a reliable source for an assignment? How can it still be useful?','Should you trust an AI-generated answer at the top of results? How would you check it?'],
  mistakes:['Typing long questions instead of keywords.','Trusting the first result or a sponsored ad.','Citing a blog or Wikipedia instead of the original research.','Not checking the date of health information.','Believing "https" means the content is true.'],
  rev:['The Internet is the network; the Web is linked pages on it.','Search engines crawl, index and rank pages.','Use keywords and operators: "", site:, filetype:, -, OR.','Use Google Scholar for academic sources.','Evaluate with CRAAP; prefer authoritative sources.'],
  hw:'Find 2 peer-reviewed articles on a psychology topic you like using Google Scholar. Save the citations for Session 4.',
  quiz:[
    {q:'Which statement is correct?', o:['The Internet and the Web are the same','The Web is a service that runs on the Internet','The Internet runs on the Web','Email is part of the Web'], a:1, e:'The Web is one internet service.'},
    {q:'Which search finds only PDF files about stress?', o:['stress pdf only','stress filetype:pdf','stress site:pdf','"stress pdf"'], a:1, e:'filetype:pdf restricts results to PDFs.'},
    {q:'Building a giant list of words found on pages is called…', o:['Crawling','Indexing','Ranking','Browsing'], a:1, e:'Indexing stores words and where they appear.'},
    {q:'Best place to find peer-reviewed psychology articles?', o:['Instagram','Google Scholar','A product website','TikTok'], a:1, e:'Scholar indexes academic literature.'},
    {q:'In CRAAP, "Purpose" asks…', o:['Is it recent?','Is it trying to inform, sell or persuade?','Who wrote it?','Is it long?'], a:1, e:'Purpose reveals bias.'}],
  terms:[['Internet','The global network of interconnected networks.'],['World Wide Web','A system of linked web pages accessed with a browser.'],['URL','Uniform Resource Locator: the address of a web page.'],['Browser','Software that opens web pages, such as Chrome or Edge.'],['Search engine','A web service that finds pages matching keywords.'],['Crawler','A program that visits and downloads web pages for indexing.'],['Search operator','A symbol or word that refines a search, such as quotes or site:.'],['Google Scholar','A search engine for scholarly literature.'],['CRAAP test','Currency, Relevance, Authority, Accuracy, Purpose — a source-evaluation checklist.']]
},
{ id:4, week:2, unit:'Basic ICT productivity tools', ic:'📧', lo:[2,3,4], book:'GO! with Microsoft Office — Outlook',
  title:'Formal Communication & Email Etiquette',
  sub:'Gmail and Outlook, the structure of a professional email, subject lines, CC/BCC, attachments and etiquette.',
  intro:'Compare two messages to a teacher: "hey sir assignmnt?" and "Dear Sir, I would like guidance on Assignment 1…". Which student gets a helpful reply? Today you learn to write emails that are clear, polite and professional.',
  obj:['Explain how email travels and name Gmail and Outlook features.','Write a formal email with subject, greeting, body, closing and signature.','Use To, CC, BCC and attachments correctly.','Apply email etiquette and avoid common mistakes.'],
  slides:[
    {k:'Concept', h:'Digital communication', ic:'💬', cmp:[['Informal channels',['WhatsApp, Messenger, SMS','Quick, casual, personal']],['Formal channels',['Email, official portals, LMS','Recorded, professional, traceable']]], tk:'Choose the channel to match the purpose.'},
    {k:'Animation', h:'Email introduction', p:'<b>Email</b> sends messages and files to an address over the internet. It is the standard for official communication in universities and workplaces.', demo:'emailflow', tk:'Email creates a written record.'},
    {k:'Tool', h:'Gmail', ic:'📮', pts:[['🆓','Free Google email; 15 GB shared with Drive and Photos'],['🏷️','Labels and categories (Primary, Promotions)'],['⏰','Schedule send and undo send'],['🔗','Works with Google Calendar, Meet and Drive']], tk:'Many university accounts use Google Workspace.'},
    {k:'Tool', h:'Microsoft Outlook', ic:'📨', pts:[['🏢','Microsoft\'s email and calendar app (desktop, web, mobile)'],['📁','Folders, rules and categories'],['🗓️','Calendar invites and Teams meetings'],['🎓','Common for university Microsoft 365 accounts']], tk:'Outlook = email + calendar for professional work.'},
    {k:'Concept', h:'Email structure', pts:[['🏷️','<b>Subject</b>'],['👋','<b>Greeting</b> (salutation)'],['📝','<b>Body</b> — purpose, details, request'],['🙏','<b>Closing</b>'],['✍️','<b>Signature</b>']], tk:'Five parts every formal email needs.'},
    {k:'Skill', h:'Writing a subject line', cmp:[['Weak',['Hi','Urgent!!!','(no subject)']],['Strong',['Request: Guidance on Assignment 1 topic','Leave application – 12 March – Roll No. 23-PSY-14','Submission: Group Project Draft (Group 3)']]], tk:'Specific subject = the reader knows what to do before opening.'},
    {k:'Skill', h:'Professional greeting', pts:[['✅','Dear Sir, / Dear Madam,'],['✅','Dear Dr. Ahmed, / Dear Ms. Fatima,'],['✅','Respected Sir, (common in Pakistan)'],['❌','hey, hi sir!!, yo, Dear teacher jee']], tk:'Use the title and surname if you know them.'},
    {k:'Skill', h:'Email body', pts:[['1️⃣','Introduce yourself briefly (name, class, roll no.) if needed'],['2️⃣','State the purpose in the first sentence'],['3️⃣','Give necessary details only'],['4️⃣','Make a clear, polite request'],['5️⃣','Short paragraphs; full words, no SMS language']], tk:'Purpose first, details next, request last.'},
    {k:'Skill', h:'Closing and signature', pts:[['🙏','Closings: Regards, / Kind regards, / Sincerely,'],['✍️','Signature: full name, program & semester, roll number, university, phone (optional)'],['⚙️','Set an automatic signature in Gmail/Outlook settings']], tk:'Your signature tells the reader who you are.'},
    {k:'Animation', h:'CC versus BCC', demo:'ccbcc', tk:'BCC protects privacy in group emails.'},
    {k:'Skill', h:'Attachments', pts:[['📎','Mention it: "Please find attached my draft."'],['📄','Send PDFs for final documents'],['🏷️','Clear file name: Ayesha_Khan_Assignment1.pdf'],['📦','Large files: share a Drive/OneDrive link (Gmail attachment limit 25 MB)'],['🔍','Check before sending — forgotten attachments are common']], tk:'Right file, right format, right name.'},
    {k:'Skill', h:'Email etiquette', pts:[['🔠','No ALL CAPS — it reads as shouting'],['🧘','Never send when angry; wait and reread'],['↩️','"Reply all" only when everyone needs the reply'],['⏳','Reply within 24–48 hours'],['🕘','Respect time — avoid late-night follow-ups']], tk:'Polite, short, clear, respectful.'},
    {k:'Animation', h:'Common email mistakes', demo:'emailcheck', tk:'Fix: subject, greeting, full sentences, signature.'},
    {k:'Example', h:'Professional email example', p:'<b>Subject:</b> Request for guidance on Assignment 1 topic – BS Psychology (Sec A)<br><br>Dear Sir,<br>I am Ayesha Khan (Roll No. 23-PSY-14). I would like your guidance on my Assignment 1 topic, "Screen time and sleep among university students". Could you please let me know whether this topic is suitable, or suggest a change? I am available during your office hours on Tuesday.<br><br>Thank you for your time.<br>Regards,<br>Ayesha Khan<br>BS Psychology, Semester 1', tk:'Clear purpose, polite request, complete signature.', n:'Fictional student. Read it aloud and ask students to label the five parts.'},
    {k:'Example', h:'Psychology academic communication', ic:'🧠', pts:[['👩‍🏫','Emailing a supervisor about your research proposal'],['🏥','Requesting an internship at a clinic or counselling centre'],['📋','Sending an information sheet & consent form to research participants'],['🔒','Never email identifiable client information unprotected']], psy:'Confidentiality is an ethical duty: share sensitive information only through approved, secure channels.', tk:'Professional email is a core skill for psychologists.'}
  ],
  lab:{t:'Activity: Email your instructor for academic guidance', steps:['Open Gmail or Outlook (university account if available).','Create an automatic signature: name, program, semester, roll number.','Write an email requesting guidance on a topic for Assignment 1.','Attach a one-paragraph PDF describing your idea, named correctly.','Send it to yourself first; check on your phone; then send to the address your instructor gives.'], out:'One professional email with attachment.'},
  disc:['When is WhatsApp acceptable for academic communication, and when is email better?','Why is BCC important for privacy? Give an example.','How should a psychologist respond to a client who emails late at night in distress? (Think about boundaries and emergency procedures.)'],
  mistakes:['Empty or vague subject lines.','SMS language: plz, u, thx, asap.','Forgetting the attachment or sending the wrong file.','Putting 80 addresses in To/CC instead of BCC.','Writing in anger or ALL CAPS.'],
  rev:['Email = formal, recorded communication (SMTP sends, IMAP syncs).','Subject, greeting, body, closing, signature.','To = action; CC = informed; BCC = hidden recipients.','Attach PDFs with clear names; mention them in the body.','Be polite, concise and respectful of time.'],
  hw:'Set up your email signature and organise your inbox with at least 2 labels/folders (e.g., "ICT-1013", "University").',
  quiz:[
    {q:'Which subject line is best?', o:['Hi','URGENT!!!','Request: Guidance on Assignment 1 topic – BS Psych (Sec A)','(no subject)'], a:2, e:'Specific subjects tell the reader the purpose.'},
    {q:'You email 60 parents who do not know each other. Put their addresses in…', o:['To','CC','BCC','Subject'], a:2, e:'BCC protects everyone\'s privacy.'},
    {q:'Which is the most professional greeting?', o:['hey sir!!','Dear Dr. Ahmed,','yo','Hi teacher jee'], a:1, e:'Title + surname is formal.'},
    {q:'Writing a whole email in CAPITALS is seen as…', o:['Formal','Shouting','Required','Friendly'], a:1, e:'All caps reads as shouting.'},
    {q:'A 60 MB video should be sent by email as…', o:['A direct attachment','A shared Drive/OneDrive link','Ten emails','A screenshot'], a:1, e:'Large files exceed attachment limits; share a link.'}],
  terms:[['Email','Electronic mail: messages sent over the internet to an address.'],['SMTP','Simple Mail Transfer Protocol, used to send email.'],['IMAP','Protocol that syncs email between the server and your devices.'],['CC','Carbon copy: visible copy to people who should be informed.'],['BCC','Blind carbon copy: recipients hidden from others.'],['Email signature','Contact block automatically added at the end of emails.'],['Netiquette','Rules of polite and respectful behaviour online.']]
},
/* ================= WEEK 3 ================= */
{ id:5, week:3, unit:'Microsoft Office & Google Workspace', ic:'📝', lo:[2,3], book:'GO! with Microsoft Office; Exploring Microsoft Office',
  title:'Microsoft Word, Excel & PowerPoint',
  sub:'The Microsoft Office suite: formatting academic reports, spreadsheet structure, formulas and charts, and clear presentations.',
  intro:'A psychology research project usually ends in three files: a <b>report</b> (Word), a <b>data sheet</b> (Excel) and a <b>presentation</b> (PowerPoint). Today you learn the core of each.',
  obj:['Identify the main parts of the Word, Excel and PowerPoint interfaces.','Format an academic report using styles, headings and page numbers.','Explain rows, columns, cell references and basic formulas; create a chart.','Design a clear presentation using one idea per slide.'],
  slides:[
    {k:'Concept', h:'Microsoft Office introduction', ic:'🗂️', pts:[['📝','<b>Word</b> — documents and reports (.docx)'],['📊','<b>Excel</b> — spreadsheets and data (.xlsx)'],['🖥️','<b>PowerPoint</b> — presentations (.pptx)'],['☁️','Microsoft 365 = desktop + web apps + OneDrive']], tk:'Three apps, one shared interface style (the Ribbon).'},
    {k:'Tool', h:'Microsoft Word', ic:'📝', p:'A <b>word processor</b> for creating, editing and formatting documents: assignments, reports, CVs, letters.', tk:'Most academic writing starts in Word.'},
    {k:'Tool', h:'Word interface', pts:[['🎀','<b>Ribbon</b> with tabs: Home, Insert, Layout, References, Review'],['📄','Document area and ruler'],['📊','Status bar: page count, word count, zoom'],['⚡','Quick Access Toolbar: Save, Undo']], tk:'Most tools are one tab away on the Ribbon.'},
    {k:'Skill', h:'Formatting documents', pts:[['🔤','Font, size, bold/italic, colour'],['↔️','Alignment and line spacing (1.5 or double)'],['•','Bullets and numbering'],['🏷️','Styles: Heading 1, Heading 2, Normal'],['📄','Page breaks, margins, page numbers']], tk:'Use styles, not manual formatting, for headings.'},
    {k:'Animation', h:'Academic report', p:'Heading styles let Word build a <b>table of contents</b> automatically. Add a title page, captions and references (References → Insert Citation, APA style).', demo:'wordtoc', tk:'Structure: Title page → Contents → Introduction → Method → Results → Discussion → References.'},
    {k:'Tool', h:'Microsoft Excel', ic:'📊', p:'A <b>spreadsheet</b> program for organising, calculating and visualising data.', psy:'Research data: each row = one participant; each column = one variable (age, gender, scores).', tk:'Excel turns numbers into answers.'},
    {k:'Concept', h:'Spreadsheet structure', pts:[['📗','<b>Workbook</b> = the file'],['📄','<b>Worksheet</b> = one sheet tab'],['▦','<b>Cell</b> = one box'],['🔢','<b>Formula bar</b> shows a cell\'s content/formula']], tk:'Workbook → worksheets → cells.'},
    {k:'Concept', h:'Rows and columns', cmp:[['Rows',['Horizontal','Numbered 1, 2, 3…','One participant per row']],['Columns',['Vertical','Lettered A, B, C…','One variable per column']]], tk:'Keep one type of data per column.'},
    {k:'Concept', h:'Cell references', pts:[['📍','Address = column letter + row number: <b>B3</b>'],['📏','Range: <b>B2:B31</b> = B2 through B31'],['🔒','Absolute reference <b>$B$1</b> stays fixed when copied'],['🔁','Relative references change when a formula is copied']], tk:'References let formulas use data instead of typed numbers.'},
    {k:'Animation', h:'Basic formulas', demo:'sheet', pts:[['➕','=SUM(B2:B31)'],['➗','=AVERAGE(B2:B31)'],['🔢','=COUNT(B2:B31)'],['⬆️','=MAX() · =MIN()'],['❓','=IF(B2>=27,"High","Normal")']], tk:'Every formula starts with = and recalculates automatically.'},
    {k:'Skill', h:'Charts', cmp:[['Choose',['Column/bar — compare groups','Line — change over time','Pie — parts of a whole (few categories)']],['Make clear',['Title + axis labels','Insert → Recommended Charts','No 3-D effects']]], tk:'One chart, one message.'},
    {k:'Tool', h:'Microsoft PowerPoint', ic:'🖥️', p:'Presentation software to support a talk with slides. Slides <b>support</b> the speaker — they are not the script.', tk:'The audience should listen to you, not read paragraphs.'},
    {k:'Concept', h:'Presentation structure', pts:[['1️⃣','Title slide'],['2️⃣','Outline / objectives'],['3️⃣','Main content (one idea per slide)'],['4️⃣','Results / examples'],['5️⃣','Conclusion and questions'],['6️⃣','References']], tk:'Tell them what you\'ll say, say it, summarise it.'},
    {k:'Animation', h:'Slide design', demo:'slidefix', pts:[['🔠','Titles 36+ pt, text 24+ pt'],['🌓','High contrast'],['🖼️','One relevant visual'],['🎞️','Few, subtle transitions']], tk:'Simple design = better understanding.'},
    {k:'Example', h:'Psychology academic workflow', ic:'🔄', pts:[['📋','Collect survey data (Google Forms or paper)'],['📊','Enter & analyse in Excel: averages, IF, chart'],['📝','Write the report in Word with headings, tables, APA references'],['🖥️','Present findings in PowerPoint (chart + 3 key points)'],['🔒','Use fictional or anonymised data; no participant names']], tk:'Office tools cover the whole research cycle.'}
  ],
  lab:{t:'Activity: Mini research package (fictional data)', steps:['Excel: enter 10 fictional participants — Gender, Sleep hours, Stress score (0–40). Calculate AVERAGE, COUNT and an IF label for scores ≥ 27. Insert a column chart.','Word: create a 1-page report "Sleep and Stress in Students" with Heading 1/2, a table, the chart, page numbers and an automatic table of contents.','PowerPoint: make 4 slides — title, method, chart, conclusion.','Save all three files in one folder named ICT_S5_YourName.'], out:'Three files: .xlsx, .docx (or PDF) and .pptx.'},
  disc:['Why is it better to use Heading styles than just making text bold and big?','When would a pie chart mislead the audience?','What makes a presentation boring? How can slide design fix it?'],
  mistakes:['Typing numbers with units ("7 hrs") so formulas cannot calculate.','Forgetting = at the start of a formula.','Making headings manually instead of using styles.','Slides full of paragraphs; too many animations.','Using real participants\' names in practice files.'],
  rev:['Word = documents; Excel = data; PowerPoint = presentations.','Styles → automatic table of contents.','Cells have addresses like B3; ranges like B2:B10.','Formulas start with =: SUM, AVERAGE, COUNT, MAX, MIN, IF.','One idea per slide; large fonts; high contrast.'],
  hw:'Watch a short official Microsoft tutorial on Excel charts. Bring your Session 5 files to the next class.',
  quiz:[
    {q:'To build an automatic table of contents in Word you must first…', o:['Use Heading styles','Make text bold','Use a bigger font','Insert a picture'], a:0, e:'The TOC reads Heading styles.'},
    {q:'Which formula calculates the average of B2 to B10?', o:['=MEAN(B2-B10)','=AVERAGE(B2:B10)','AVERAGE B2 B10','=SUM(B2:B10)/2'], a:1, e:'AVERAGE with the range B2:B10.'},
    {q:'The cell in column C, row 5 is…', o:['5C','C5','CC5','R5'], a:1, e:'Column letter then row number.'},
    {q:'A line chart is best for…', o:['Change over time','Parts of a whole','Text','Pictures'], a:0, e:'Lines show trends.'},
    {q:'A good slide has…', o:['A full paragraph','One main idea with a few short points','Ten fonts','Flying text'], a:1, e:'One idea per slide.'}],
  terms:[['Microsoft 365','Microsoft\'s subscription suite including Word, Excel, PowerPoint, Outlook and OneDrive.'],['Ribbon','The tabbed toolbar in Office applications.'],['Style','A saved set of formatting applied consistently, e.g., Heading 1.'],['Workbook','An Excel file containing one or more worksheets.'],['Cell reference','The address of a cell, e.g., B3.'],['Formula','An expression starting with = that calculates a value.'],['Function','A built-in formula such as SUM or AVERAGE.'],['Chart','A visual representation of data.']]
},
{ id:6, week:3, unit:'Microsoft Office & Google Workspace', ic:'🤝', lo:[2,3], book:'Google Workspace Learning Center',
  title:'Google Workspace & Online Collaboration',
  sub:'Google Docs, Sheets and Slides; sharing, permissions, comments, real-time co-editing and version history. Assignment 1 released.',
  assess:'Assignment-1',
  intro:'Group work often means emailing "Final_v3_REAL_final.docx" back and forth. Google Workspace lets the whole group edit <b>one file</b> at the same time — with every change recorded.',
  obj:['Create documents, spreadsheets and presentations in Google Docs, Sheets and Slides.','Share files with appropriate permissions.','Collaborate using comments, suggestions and real-time editing.','Use version history to review and restore work.'],
  slides:[
    {k:'Concept', h:'Google Workspace introduction', ic:'🧰', p:'Google\'s free, browser-based productivity suite (with a Google account): <b>Docs, Sheets, Slides, Forms, Drive, Gmail, Meet, Calendar</b>.', tk:'Everything auto-saves to Google Drive.'},
    {k:'Tool', h:'Google Docs', ic:'📄', pts:[['📝','Word processor in the browser'],['🎙️','Voice typing (Tools → Voice typing)'],['📑','Headings & automatic table of contents'],['📤','Export as .docx or .pdf']], tk:'Docs ≈ Word, online and collaborative.'},
    {k:'Tool', h:'Google Sheets', ic:'📊', pts:[['🔢','Same formulas as Excel: SUM, AVERAGE, IF'],['📋','Linked automatically to Google Forms responses'],['📈','Insert → Chart'],['🔽','Filters and conditional formatting']], tk:'Sheets + Forms = quick survey research.'},
    {k:'Tool', h:'Google Slides', ic:'🖼️', pts:[['🎨','Themes and layouts'],['🗒️','Speaker notes and presenter view'],['🔗','Present directly in Meet'],['📤','Download as .pptx or .pdf']], tk:'Slides ≈ PowerPoint, built for teamwork.'},
    {k:'Skill', h:'Creating documents', pts:[['➕','drive.google.com → New → Google Docs (or docs.new)'],['🏷️','Rename at the top-left immediately'],['📑','Apply Heading 1/2 from the style menu'],['📁','Move it into the right Drive folder']], tk:'Name and file it from the start.'},
    {k:'Skill', h:'Creating spreadsheets', pts:[['➕','New → Google Sheets (or sheets.new)'],['🧾','Row 1 = headings; freeze it (View → Freeze)'],['🔢','Enter data — one variable per column'],['🧮','Add formulas and a chart']], tk:'Clean structure first, formulas second.'},
    {k:'Skill', h:'Creating presentations', pts:[['➕','New → Google Slides (or slides.new)'],['🎨','Choose a simple, high-contrast theme'],['🧩','Use layouts: Title, Title + body, Section'],['🗒️','Write speaker notes under each slide']], tk:'Use layouts — don\'t drag random text boxes.'},
    {k:'Skill', h:'Sharing documents', pts:[['🔗','Click <b>Share</b> (top-right)'],['📧','Add people by email, or copy a link'],['🔐','Choose: Restricted (only added people) or Anyone with the link'],['✉️','Add a short message when sharing']], tk:'Share deliberately, not by default.'},
    {k:'Animation', h:'Editing permissions', demo:'share', tk:'Viewer · Commenter · Editor — give the least access needed.'},
    {k:'Skill', h:'Comments', pts:[['💬','Select text → Insert comment (Ctrl+Alt+M)'],['@','Mention someone with @name to notify them'],['✅','Resolve when done'],['✏️','Suggesting mode: edits shown as suggestions to accept/reject']], tk:'Discuss inside the document, not in 10 WhatsApp messages.'},
    {k:'Animation', h:'Collaborative editing', demo:'coedit', tk:'Many people, one file, no overwriting.'},
    {k:'Animation', h:'Version history', demo:'versions', p:'File → Version history → See version history. Name important versions ("Submitted draft").', tk:'Mistakes can always be undone.'},
    {k:'Concept', h:'Real-time collaboration', cmp:[['Benefits',['Everyone sees the latest version','Work from anywhere, any device','Fair, visible contribution record']],['Rules',['Agree who writes which section','Use comments for disagreements','Do not delete others\' work without discussion']]], tk:'Technology works when the team agrees on rules.'},
    {k:'Example', h:'Group academic work', ic:'👥', pts:[['📁','One shared folder per group'],['📄','One Doc with sections assigned in comments'],['📊','One Sheet for data; one Slides deck'],['🗓️','Meet for weekly check-ins'],['🕓','Version history shows each member\'s contribution']], tk:'Transparent teamwork reduces conflicts.'},
    {k:'Example', h:'Psychology research collaboration', ic:'🧠', p:'A group studies "Social media use and loneliness" (fictional class project).', pts:[['📝','Google Form questionnaire with an informed-consent page'],['📊','Responses flow into Sheets automatically'],['🔒','Restricted sharing — group + supervisor only'],['🗒️','Docs for the report; Slides for the presentation']], psy:'Keep participant data anonymous and share only with the research team.', tk:'Collaboration must still protect confidentiality.'}
  ],
  lab:{t:'Activity: Collaborate in real time', steps:['Form groups of 3. One member creates a Google Doc "Group Notes – Session 6" and shares it as Editor.','Each member writes one paragraph at the same time on: Docs, Sheets or Slides.','Add one comment with an @mention; the mentioned person replies and resolves it.','Switch to Suggesting mode and make one suggestion; the owner accepts it.','Open Version history and name the current version "Class activity".'], out:'Screenshot of version history showing all members.'},
  disc:['What are the risks of "Anyone with the link can edit"?','How can version history help resolve disagreements about who did the work?','Should a supervisor be an Editor or a Commenter on a student\'s thesis? Why?'],
  mistakes:['Sharing as Editor when Viewer or Commenter is enough.','Using "Anyone with the link" for files with personal data.','Deleting a group member\'s text without discussion.','Downloading and re-uploading copies, creating version confusion.','Forgetting to rename "Untitled document".'],
  rev:['Google Workspace: Docs, Sheets, Slides, Forms, Drive, Meet.','Share with Restricted access and the least permission needed.','Comments, @mentions and Suggesting mode support teamwork.','Many people can edit one file at the same time.','Version history lets you review and restore earlier versions.'],
  hw:'Start Assignment 1 (details below). Create your assignment folder in Drive or OneDrive.',
  quiz:[
    {q:'Which permission lets someone add comments but not change the text?', o:['Viewer','Commenter','Editor','Owner'], a:1, e:'Commenters can comment and suggest only.'},
    {q:'Responses from a Google Form can be sent automatically to…', o:['Google Sheets','Paint','Notepad','A USB'], a:0, e:'Forms link to a response spreadsheet.'},
    {q:'A group member deleted a section by mistake. The best fix is…', o:['Rewrite it from memory','Restore an earlier version from Version history','Start a new document','Ask the teacher'], a:1, e:'Version history keeps earlier versions.'},
    {q:'"Suggesting" mode in Google Docs…', o:['Deletes text','Shows edits as suggestions the owner can accept or reject','Translates text','Prints the document'], a:1, e:'Like Track Changes in Word.'},
    {q:'Typing <b>docs.new</b> in the browser…', o:['Opens Gmail','Creates a new Google Doc','Deletes a file','Opens Word'], a:1, e:'Shortcut to create a new Doc.'}],
  assessment:{ kind:'assignment', title:'Assignment 1 — ICT Productivity Project', covers:'Weeks 1–3 (ICT basics, search, email, Office & Google Workspace)',
    instructions:['Individual assignment. Identical or partially identical submissions receive zero (course policy).','Choose ONE option: (A) formatted academic report, (B) data spreadsheet with analysis, (C) academic presentation, or (D) a Google Workspace collaborative project (pairs allowed only if your instructor permits).','Use fictional or anonymous data only — no real names of participants.','Deadline, marks and any extra requirements will be announced by your instructor.'],
    tasks:['<b>Option A — Report (Word/Docs):</b> 3–4 pages on "Screen time and sleep in university students": title page, automatic table of contents, Heading 1/2, one table with caption, page numbers, at least 3 APA references found with Google Scholar.','<b>Option B — Spreadsheet (Excel/Sheets):</b> fictional data for 20 participants (gender, daily screen time, sleep hours, stress score); use SUM, AVERAGE, COUNT, MAX/MIN and IF; one correctly labelled chart; a 5-line written interpretation.','<b>Option C — Presentation (PowerPoint/Slides):</b> 8–10 slides on an ICT tool useful for psychology students; one idea per slide, large fonts, at least one chart or diagram, speaker notes on every slide, references slide.','<b>Option D — Collaboration (Google Workspace):</b> a shared folder containing a Form, its response Sheet with a chart, and a Doc summary; show version history and comments demonstrating each member\'s contribution.'],
    submission:['Submit the final file as PDF (and the original .docx/.xlsx/.pptx or a View link for Google files).','File name: RollNo_Name_A1.pdf (e.g., 23-PSY-14_AyeshaKhan_A1.pdf).','Submit through the channel your instructor specifies (LMS or email with a formal subject line).'],
    reflection:['Which ICT tool features saved you the most time?','What problem did you face and how did you solve it?','How did you make sure your data and sources were ethical?'],
    example:'<b>Example (Option B, fictional):</b> Columns A–E: ID, Gender, Screen time (h), Sleep (h), Stress (0–40). Row 22: =AVERAGE(C2:C21) → 5.6 h; =AVERAGE(D2:D21) → 6.4 h. Column F: =IF(E2>=27,"High","Normal"). Chart: clustered column "Average sleep by screen-time group (≤4 h vs >4 h)". Interpretation: "Students with more than 4 hours of screen time reported about 1 hour less sleep on average in this fictional sample. This does not prove causation."'
  },
  terms:[['Google Workspace','Google\'s cloud productivity suite: Docs, Sheets, Slides, Drive, Gmail, Meet and more.'],['Google Docs','Browser-based word processor with real-time collaboration.'],['Google Sheets','Browser-based spreadsheet application.'],['Google Slides','Browser-based presentation application.'],['Real-time collaboration','Several people editing the same file at the same time.'],['Suggesting mode','Docs mode in which edits appear as suggestions to accept or reject.'],['Version history','A saved record of earlier versions of a file that can be restored.'],['Permission','Level of access to a shared file: Viewer, Commenter or Editor.']]
},
/* ================= WEEK 4 ================= */
{ id:7, week:4, unit:'Cloud storage & digital note-taking', ic:'☁️', lo:[2,3,4], book:'Technology in Action — Cloud computing',
  title:'Cloud Storage & File Sharing',
  sub:'Cloud computing; Google Drive, Dropbox and OneDrive; uploading, downloading, sharing, permissions, sync, backup and security.',
  intro:'A student\'s laptop is stolen two days before her thesis deadline. Her friend with the same problem is calm — because her thesis was in the cloud. Today you learn to store, sync, share and back up files safely.',
  obj:['Explain cloud computing and cloud storage.','Compare Google Drive, Dropbox and OneDrive.','Upload, download, share and sync files with suitable permissions.','Apply backup and cloud-security practices to academic files.'],
  slides:[
    {k:'Introduction', h:'Cloud storage introduction', ic:'☁️', p:'Files stored on a provider\'s internet-connected servers — available on any signed-in device.', ex:'Start an assignment on a lab PC, edit it on your phone on the bus, finish at home.', tk:'"The cloud" = someone else\'s computers in a data centre.'},
    {k:'Concept', h:'What is cloud computing?', pts:[['💾','<b>Storage</b> — Drive, OneDrive, Dropbox'],['🧰','<b>Software as a Service</b> — Gmail, Google Docs, Microsoft 365 online'],['🖥️','<b>Computing power</b> — servers rented by companies'],['🌐','Accessed over the internet, on demand']], tk:'Cloud storage is one part of cloud computing.'},
    {k:'Concept', h:'Cloud storage', cmp:[['Advantages',['Access anywhere','Automatic backup','Easy sharing']],['Limitations',['Needs internet','Limited free space','Privacy depends on settings & provider']]], tk:'Know both sides.'},
    {k:'Tool', h:'Google Drive', ic:'🟢', pts:[['🆓','15 GB free, shared with Gmail and Google Photos'],['📄','Opens and creates Docs, Sheets, Slides'],['🎓','Used by Google Classroom for submissions'],['🔍','Powerful search, including text in images/PDFs']], tk:'Best if you live in the Google ecosystem.', n:'Free storage limits can change — check the provider\'s site.'},
    {k:'Tool', h:'Dropbox', ic:'📦', pts:[['🆓','Basic free plan (2 GB)'],['🔄','Known for simple, reliable syncing'],['🔗','Easy share links and file requests'],['💻','Works on Windows, macOS, Android, iOS']], tk:'Simple and platform-neutral.'},
    {k:'Tool', h:'OneDrive', ic:'🔵', pts:[['🆓','5 GB free; more with Microsoft 365'],['🪟','Built into Windows File Explorer'],['📝','Opens Word, Excel, PowerPoint online'],['🛡️','Personal Vault for sensitive files']], tk:'Best if you use Microsoft Office.'},
    {k:'Animation', h:'Uploading files', demo:'upload', pts:[['⬆️','New → File upload / Folder upload'],['🖱️','Or drag and drop into the browser window']], tk:'Upload = copy from your device to the cloud.'},
    {k:'Skill', h:'Downloading files', pts:[['⬇️','Right-click → Download'],['📄','Google files download as .docx/.xlsx/.pptx or PDF'],['📴','Offline mode lets you open files without internet'],['🧹','Delete downloaded copies from shared/lab PCs']], tk:'Download = copy from the cloud to your device.'},
    {k:'Skill', h:'Sharing files', pts:[['🔗','Share → add people or copy link'],['📧','Notify people with a short message'],['📥','Dropbox/OneDrive "file request" to collect files'],['⏳','Some services allow expiry dates for links']], tk:'Share the file, not 10 copies of it.'},
    {k:'Animation', h:'Access permissions', demo:'share', tk:'Least access needed: Viewer < Commenter < Editor.'},
    {k:'Animation', h:'Synchronisation', demo:'cloudsync', p:'Install the desktop/mobile app; a synced folder keeps every device identical.', tk:'Delete in one place = deleted everywhere (until trash is emptied).'},
    {k:'Animation', h:'Backup', demo:'backup321', tk:'3 copies · 2 media · 1 off-site.'},
    {k:'Concept', h:'Cloud collaboration', pts:[['📁','Shared folders for group projects'],['✏️','Co-editing Office/Google files'],['💬','Comments and activity panels show who did what'],['🕓','File versions can be restored']], tk:'One shared source of truth.'},
    {k:'Safety', h:'Cloud security', pts:[['🔑','Strong, unique password + 2-step verification'],['🔗','Avoid public links for private data'],['🚪','Sign out on shared and lab computers'],['🎣','Beware fake "shared document" phishing emails'],['🧑‍⚕️','Never upload confidential client data to personal accounts']], tk:'Convenience must not cost privacy.'},
    {k:'Example', h:'Psychology academic file management', ic:'🗂️', p:'<b>ICT-1013 / 01_Notes · 02_Assignments · 03_Group_Project · 04_Readings</b><br>File names: 2026-03-10_A1_Report_v2.docx', psy:'Research data: anonymised IDs (P01, P02), a password-protected folder, shared only with the research team and supervisor, following ethics approval.', tk:'Organised + secure = professional.'}
  ],
  lab:{t:'Activity: Build and share an academic folder structure', steps:['In Google Drive or OneDrive, create: ICT-1013 → Notes, Assignments, Group Project, Readings.','Upload one file and open it on your phone (sync check).','Share the Group Project folder with 2 classmates as Editors.','Share one file with your instructor as Viewer (Restricted, not "anyone with link").','Download a Google Doc as PDF, then delete the download if on a lab PC.'], out:'Screenshot of folders and the sharing dialog.'},
  disc:['Is it safe to keep your only copy of a thesis in one cloud account? Why or why not?','Who can see a file shared with "Anyone with the link"?','What rules should a counselling centre follow before storing records in the cloud?'],
  mistakes:['Thinking a synced delete keeps the file on other devices.','Using "Anyone with the link" by default.','Staying signed in on a lab computer.','Keeping only one copy of important work.','Opening "shared document" links from unknown senders.'],
  rev:['Cloud storage = files on remote servers; part of cloud computing.','Drive (Google), OneDrive (Microsoft), Dropbox.','Upload / download / share / sync.','Viewer, Commenter, Editor — least access needed.','3-2-1 backup; strong password + 2-step verification.'],
  hw:'Turn on 2-step verification for your main Google or Microsoft account. Revise Weeks 1–4 for Quiz 1 (next session).',
  quiz:[
    {q:'Which permission is safest for sharing a final report with your teacher?', o:['Editor','Viewer','Anyone with link – Editor','Owner'], a:1, e:'Viewer lets them read only.'},
    {q:'Which service is built into Windows and Microsoft Office?', o:['Dropbox','OneDrive','Google Drive','iCloud'], a:1, e:'OneDrive is Microsoft\'s.'},
    {q:'The "1" in the 3-2-1 backup rule means…', o:['1 USB','1 copy off-site','1 password','1 folder'], a:1, e:'One copy away from your location, e.g., the cloud.'},
    {q:'Copying a file from the cloud to your computer is…', o:['Uploading','Downloading','Syncing','Sharing'], a:1, e:'Download = cloud → device.'},
    {q:'Main limitation of cloud storage?', o:['Needs internet access','Cannot store photos','Cannot be shared','Only for laptops'], a:0, e:'Without internet you cannot sync.'}],
  terms:[['Cloud computing','Delivery of computing services such as storage and software over the internet.'],['Upload','Copying a file from your device to an online service.'],['Download','Copying a file from an online service to your device.'],['Sync','Keeping files identical across multiple devices.'],['Google Drive','Google\'s cloud storage integrated with Docs, Sheets and Slides.'],['OneDrive','Microsoft\'s cloud storage integrated with Microsoft 365.'],['Dropbox','Cloud storage and file-sharing service.'],['Backup','An extra copy of data kept in case the original is lost.'],['2-step verification','Login requiring a second proof, such as a code on your phone.']]
},
{ id:8, week:4, unit:'Cloud storage & digital note-taking', ic:'🗒️', lo:[2,3], book:'Technology in Action',
  title:'Evernote & OneNote: Digital Note-Taking',
  sub:'Digital notebooks, sections and pages, searchable and multimedia notes, research notes and study organisation. Quiz 1 (Weeks 1–4).',
  assess:'Quiz-1',
  intro:'Your notes are in three notebooks, two WhatsApp groups and a hundred phone photos. Before exams you cannot find anything. Digital note apps put everything in one searchable place.',
  obj:['Compare traditional and digital note-taking.','Organise notes in OneNote (notebook → section → page) and Evernote (notebooks + tags).','Create searchable, multimedia and research notes.','Apply note-taking best practices such as the Cornell method.'],
  slides:[
    {k:'Concept', h:'Digital note-taking', ic:'🗒️', p:'Using apps to <b>capture, organise, search and sync</b> notes — text, images, audio, web pages and handwriting.', tk:'Your second brain, available on every device.'},
    {k:'Compare', h:'Traditional versus digital notes', cmp:[['Traditional (paper)',['No battery or internet needed','Handwriting may help memory','Easy to lose; hard to search']],['Digital',['Searchable in seconds','Synced and backed up','Mix text, photos, audio, links']]], tk:'Many students combine both: write by hand, then digitise.'},
    {k:'Tool', h:'Evernote', ic:'🐘', pts:[['📒','Notebooks and <b>tags</b>'],['✂️','Web Clipper saves articles'],['🔍','Search inside images and PDFs'],['💲','Free plan has limits (devices/notes); paid plans offer more']], tk:'Tags let one note belong to many topics.'},
    {k:'Tool', h:'OneNote', ic:'🟣', pts:[['🆓','Free, part of Microsoft 365 / Windows'],['📓','Binder layout: Notebook → Section → Page'],['✍️','Type, draw or handwrite anywhere on the page'],['☁️','Syncs through OneDrive']], tk:'OneNote = a free-form digital binder.'},
    {k:'Concept', h:'Digital notebook', p:'A <b>notebook</b> is the top-level container — one per semester or per major area.', ex:'Notebook: "BS Psychology – Semester 1".', tk:'Few notebooks, well organised.'},
    {k:'Concept', h:'Sections and pages', pts:[['📓','<b>Notebook:</b> BS Psychology – Sem 1'],['📑','<b>Section:</b> ICT-1013 · Intro to Psychology · English'],['📄','<b>Page:</b> Session 8 – Note-taking'],['🏷️','Evernote equivalent: notebooks + tags']], tk:'Notebook → Section → Page mirrors a real binder.'},
    {k:'Animation', h:'Organising notes', demo:'notes', tk:'Capture → Organise → Search → Sync.'},
    {k:'Skill', h:'Searchable notes', pts:[['🔍','Search every word across all notebooks'],['🖼️','OCR finds text inside photos of the whiteboard'],['🏷️','Tags: #exam, #research, #cognition'],['📅','Sort by date to find recent notes']], tk:'If it is searchable, it is never lost.'},
    {k:'Skill', h:'Multimedia notes', pts:[['📷','Photos of slides and whiteboard'],['🎙️','Audio recordings (with permission)'],['🔗','Links to videos and articles'],['✏️','Drawings and diagrams with a pen or finger']], tk:'Use the format that explains the idea best.'},
    {k:'Skill', h:'Study organisation', pts:[['☑️','To-do lists and checkboxes for assignments'],['⏰','Reminders for deadlines'],['📚','Exam revision page per course'],['🔁','Weekly review: summarise and tag']], tk:'Notes are only useful if you review them.'},
    {k:'Skill', h:'Research notes', pts:[['❝','Record full citation with each note'],['✂️','Clip abstracts of useful papers'],['🧠','Separate "what the source says" from "my idea"'],['🔗','Link related notes together']], psy:'For a literature review, keep one page per article: citation, aim, sample, findings, limitations.', tk:'Good research notes prevent accidental plagiarism.'},
    {k:'Skill', h:'Note-taking best practices — Cornell method', cmp:[['Layout',['Right: main notes during class','Left: key questions / cue words','Bottom: 2–3 line summary']],['Why it works',['Encourages active recall','Built-in revision questions','Summaries improve understanding']]], tk:'Write less, think more.'},
    {k:'Example', h:'Psychology student example', ic:'👩‍🎓', p:'Hina\'s OneNote: Notebook "BS Psych Sem 1" → Section "Intro to Psychology" → Page "Memory models" with lecture notes, a photo of the Atkinson–Shiffrin diagram, a clipped article (with citation), cue questions and a 3-line summary tagged #midterm.', tk:'One system, used every week.'}
  ],
  lab:{t:'Activity: Build your study notebook', steps:['Install OneNote or Evernote (or use the web version).','Create a notebook for this semester with a section/notebook per course.','Make a Cornell-style page for today\'s session.','Add a photo of the board and test search for a word inside it.','Clip one article about "sleep and memory" and record its citation.'], out:'Screenshot of your notebook structure.'},
  disc:['Is handwriting or typing better for learning? What does your experience say?','What are the ethics of recording a lecture or a counselling session?','How could digital notes help a psychology student during a research project?'],
  mistakes:['Copying slides word for word instead of summarising.','Many notebooks with no structure.','Recording people without permission.','Clipping articles but never reading or citing them.','Never reviewing notes until the night before exams.'],
  rev:['Digital notes are searchable, synced and multimedia.','OneNote: Notebook → Section → Page.','Evernote: notebooks + tags + web clipper.','Record citations with research notes.','Cornell: notes, cues, summary.'],
  hw:'Review your Quiz 1 feedback. Prepare for Week 5: install Google Meet or Zoom on your phone.',
  quiz:[
    {q:'OneNote organises notes as…', o:['Folders → Files','Notebook → Section → Page','Tags only','Sheets → Cells'], a:1, e:'OneNote mimics a binder.'},
    {q:'Evernote\'s tool for saving web articles is the…', o:['Web Clipper','Mail Merge','PivotTable','Slide Sorter'], a:0, e:'The Web Clipper saves web pages into notes.'},
    {q:'In the Cornell method, the bottom area is for…', o:['Doodles','A short summary','Phone numbers','Photos only'], a:1, e:'Summarise in 2–3 lines.'},
    {q:'Searching text inside a whiteboard photo uses…', o:['OCR','SMTP','Bluetooth','GPS'], a:0, e:'Optical Character Recognition.'},
    {q:'Before recording a lecture you should…', o:['Hide the phone','Ask the teacher\'s permission','Record secretly','Post it online'], a:1, e:'Always get consent.'}],
  assessment:{ kind:'quiz', title:'Quiz 1 — Weeks 1–4', covers:'ICT fundamentals, scope & emerging tech, internet & search, email, Office, Google Workspace, cloud storage, note-taking',
    instructions:['Closed-book unless your instructor says otherwise.','Answer all parts. Read each scenario carefully.','Time and marks are announced by your instructor.'],
    mcq:[
      {q:'Which component is <b>temporary</b> memory?', o:['SSD','RAM','USB drive','Cloud'], a:1, e:'RAM loses its content when power is off.'},
      {q:'A clinic sends appointment reminders by SMS. Which ICT domain is this?', o:['Healthcare','Entertainment','Governance','Gaming'], a:0, e:'ICT supports healthcare services.'},
      {q:'To search only Pakistani university sites, add…', o:['filetype:pk','site:.edu.pk','"edu.pk"','-edu'], a:1, e:'site: restricts the domain.'},
      {q:'You must email all 45 classmates without revealing their addresses. Use…', o:['To','CC','BCC','Reply all'], a:2, e:'BCC hides recipients.'},
      {q:'Which formula labels a score in B2 as "High" if it is 27 or more?', o:['=IF(B2>=27,"High","Normal")','=SUM(B2>27)','=HIGH(B2)','IF B2 27 High'], a:0, e:'IF(condition, value if true, value if false).'},
      {q:'In Google Docs, edits that the owner can accept or reject are made in…', o:['Viewing mode','Suggesting mode','Print layout','Outline'], a:1, e:'Suggesting mode records proposed edits.'},
      {q:'OneNote\'s structure is…', o:['Notebook → Section → Page','Folder → Sheet → Cell','Album → Photo','Inbox → Label'], a:0, e:'Like a binder.'},
      {q:'Your laptop fails; your files are safe because they were in OneDrive. This shows cloud storage provides…', o:['Faster typing','Backup and access anywhere','Free internet','Better screens'], a:1, e:'Cloud copies survive device loss.'}],
    tf:[
      {q:'The World Wide Web and the Internet are exactly the same thing.', a:false, e:'The Web is a service that runs on the Internet.'},
      {q:'An operating system is an example of system software.', a:true, e:'It manages hardware and runs applications.'},
      {q:'"https" guarantees that the information on a website is true.', a:false, e:'It only means the connection is encrypted.'},
      {q:'Version history in Google Docs can restore an earlier version of a file.', a:true, e:'File → Version history.'},
      {q:'Deleting a file in a synced folder on your laptop keeps it safe on your phone.', a:false, e:'Sync deletes it everywhere (until the trash is emptied).'}],
    short:[
      {q:'Differentiate between data and information with a psychology example.', a:'Data are raw facts (e.g., 20 answers on a 1–5 scale). Information is processed data with meaning (e.g., a total anxiety score of 32/40 interpreted as "high").'},
      {q:'List the five parts of a formal email.', a:'Subject line, greeting/salutation, body, closing, signature.'},
      {q:'Name three search operators and what each does.', a:'"…" exact phrase; site: restricts to a website/domain; filetype: restricts to a file type; - excludes a word; OR includes alternatives.'},
      {q:'What is the 3-2-1 backup rule?', a:'Keep 3 copies of important data, on 2 different types of media, with 1 copy off-site (e.g., cloud).'}],
    app:[
      {q:'Scenario: A classmate shares a group-project Doc as "Anyone with the link can edit" and posts the link in a public Facebook group. Identify two risks and the correct setting.', a:'Risks: strangers can edit/delete work; personal or research data may be exposed. Correct: Restricted access, add group members by email as Editors and the teacher as Viewer/Commenter.'},
      {q:'Scenario: You need recent peer-reviewed articles on "exam anxiety in university students". Describe your search strategy.', a:'Use Google Scholar with keywords: "exam anxiety" "university students"; filter years (e.g., since 2020); try synonyms (test anxiety); check "Cited by"; open PDFs; evaluate with CRAAP; save citations in APA.'},
      {q:'Scenario: You collected sleep hours for 15 fictional participants in Excel. Which functions and chart would you use to report the results?', a:'AVERAGE for mean sleep, COUNT for number of participants, MAX/MIN for range, IF to label short sleepers; a column chart comparing groups (or a histogram); add a title and axis labels.'}],
    note:'Model answers are guides; equivalent correct answers are acceptable.'
  },
  terms:[['Digital note-taking','Capturing and organising notes with apps that sync and search.'],['OneNote','Microsoft\'s digital notebook organised into notebooks, sections and pages.'],['Evernote','Note-taking app using notebooks, tags and web clipping.'],['Tag','A keyword label used to group notes across notebooks.'],['Web clipper','Browser tool that saves web content into a note app.'],['OCR','Optical Character Recognition: converting text in images into searchable text.'],['Cornell notes','A note format with main notes, a cue column and a summary.']]
}
);
